/**
 * Reader's vendored rendering libraries (#653): the raw source strings the
 * Plugin carries, the nested pdf.js core Worker, and the promise that loading
 * the Plugin entry evaluates nothing. Provenance lives in `vendor/README.md`;
 * the strings are regenerated by `node scripts/vendor-reader.mjs`.
 */

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  foliateSource,
  pdfDisplaySource,
  pdfViewerCss,
  purifySource,
  startPdfCore,
} from "./loaders";

/** The pdf.js release the vendored sources must carry. */
const PDFJS_VERSION = "6.4.299";

/** The Mozilla licence banner both pdf.js modules start with. */
const PDFJS_BANNER = "/**\n * @licstart";

/** A Blob that keeps its parts, so the test can read the source it wrapped. */
class RecordedBlob {
  constructor(
    readonly parts: string[],
    readonly options?: BlobPropertyBag
  ) {}
}

/** A Worker that records how it was started instead of running anything. */
class RecordedWorker {
  readonly terminate = vi.fn();
  constructor(
    readonly url: string,
    readonly options?: WorkerOptions
  ) {
    workers.push(this);
  }
}

/** Every Worker started through the stubbed global. */
const workers: RecordedWorker[] = [];
/** Every Blob handed to `URL.createObjectURL`. */
const blobs: RecordedBlob[] = [];

/** The `blob:` URL `startPdfCore` gives each Blob, in creation order. */
const CORE_URL = "blob:pdfjs-core";
const BOOTSTRAP_URL = "blob:pdfjs-bootstrap";

/** Stubs the Worker, Blob, and object-URL globals `startPdfCore` needs. */
function stubWorkerGlobals(): {
  createObjectURL: ReturnType<typeof vi.fn>;
  revokeObjectURL: ReturnType<typeof vi.fn>;
} {
  workers.length = 0;
  blobs.length = 0;
  const createObjectURL = vi.fn((blob: RecordedBlob) => {
    blobs.push(blob);
    return blobs.length === 1 ? CORE_URL : BOOTSTRAP_URL;
  });
  const revokeObjectURL = vi.fn();
  vi.stubGlobal("Blob", RecordedBlob);
  vi.stubGlobal("Worker", RecordedWorker);
  vi.stubGlobal("URL", { createObjectURL, revokeObjectURL });
  return { createObjectURL, revokeObjectURL };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("vendored source strings", () => {
  it("carries the pdf.js display module, banner and version intact", () => {
    const source = pdfDisplaySource();
    expect(source.length).toBeGreaterThan(100_000);
    expect(source.startsWith(PDFJS_BANNER)).toBe(true);
    expect(source).toContain(PDFJS_VERSION);
  });

  it("carries the pdf.js core worker, banner and version intact", () => {
    const { createObjectURL } = stubWorkerGlobals();
    const core = startPdfCore();
    expect(createObjectURL).toHaveBeenCalledTimes(2);
    const [coreBlob] = blobs;
    expect(coreBlob.options?.type).toBe("text/javascript");
    const [source] = coreBlob.parts;
    expect(source.length).toBeGreaterThan(1_000_000);
    expect(source.startsWith(PDFJS_BANNER)).toBe(true);
    expect(source).toContain(PDFJS_VERSION);
    core.dispose();
  });

  it("starts the core from a bootstrap module that imports it by blob: URL", () => {
    stubWorkerGlobals();
    const core = startPdfCore();
    const [, bootstrapBlob] = blobs;
    expect(bootstrapBlob.options?.type).toBe("text/javascript");
    const [bootstrap] = bootstrapBlob.parts;
    expect(bootstrap).toContain(
      `import { WorkerMessageHandler } from ${JSON.stringify(CORE_URL)};`
    );
    expect(bootstrap).toContain("WorkerMessageHandler.initializeFromPort(port)");
    expect(bootstrap).toContain("port.start()");
    core.dispose();
  });

  it("carries pdf.js's viewer CSS, text layer rules included", () => {
    const css = pdfViewerCss();
    expect(css.startsWith("/* Copyright 2014 Mozilla Foundation")).toBe(true);
    expect(css).toContain(".textLayer");
  });

  it("carries the foliate parsers as code, not as a comment", () => {
    const source = foliateSource();
    expect(source.length).toBeGreaterThan(10_000);
    expect(source).toMatch(/^[\w$]/);
  });

  it("carries DOMPurify's browser build as code", () => {
    const source = purifySource();
    expect(source.length).toBeGreaterThan(50_000);
    expect(source).toMatch(/^[\w$]/);
    expect(source).toContain("DOMPurify");
  });
});

describe("startPdfCore", () => {
  it("starts a module Worker from the bootstrap's blob: URL", () => {
    stubWorkerGlobals();
    const core = startPdfCore();
    expect(workers).toHaveLength(1);
    expect(core.worker).toBe(workers[0]);
    expect(workers[0].url).toBe(BOOTSTRAP_URL);
    expect(workers[0].options).toEqual({ type: "module" });
    core.dispose();
  });

  it("terminates the Worker and releases both blob: URLs on dispose", () => {
    const { revokeObjectURL } = stubWorkerGlobals();
    const core = startPdfCore();
    expect(workers[0].terminate).not.toHaveBeenCalled();
    core.dispose();
    expect(workers[0].terminate).toHaveBeenCalledTimes(1);
    expect(revokeObjectURL).toHaveBeenCalledWith(CORE_URL);
    expect(revokeObjectURL).toHaveBeenCalledWith(BOOTSTRAP_URL);
  });
});

describe("the foliate bundle", () => {
  it("exports the parser surface Reader needs from one self-contained module", async () => {
    const source = foliateSource();
    const url = `data:text/javascript;base64,${Buffer.from(source).toString("base64")}`;
    const module = (await import(/* @vite-ignore */ url)) as Record<string, unknown>;
    expect(Object.keys(module).sort()).toEqual([
      "CFI",
      "EPUB",
      "MOBI",
      "isMOBI",
      "makeComicBook",
      "makeFB2",
      "search",
      "unzlibSync",
    ]);
    expect(typeof module.EPUB).toBe("function");
    expect(typeof module.MOBI).toBe("function");
    expect(typeof module.isMOBI).toBe("function");
    expect(typeof module.makeFB2).toBe("function");
    expect(typeof module.makeComicBook).toBe("function");
    expect(typeof module.search).toBe("function");
    expect(typeof module.unzlibSync).toBe("function");
    expect(module.CFI).toBeTypeOf("object");
  });
});

describe("the Plugin entry", () => {
  it("starts no Worker when the entry and its loaders load", async () => {
    const WorkerSpy = vi.fn();
    vi.stubGlobal("Worker", WorkerSpy);
    await import("./loaders");
    await import("./index");
    expect(WorkerSpy).not.toHaveBeenCalled();
  });
});
